export type HarmonyLessonId = typeof harmonyLessons[number]['id'];
export type LessonExample = { title: string; context: Chord; chords: Chord[] };

export const lessonSource = (lesson: typeof harmonyLessons[number]) =>
  `https://www.youtube.com/watch?v=${lesson.videoId}&t=${lesson.seconds}s`;

export const lessonExamples = (
  id: HarmonyLessonId,
  tonic: string,
  mode: KeyMode,
): LessonExample[] => {
  const major = mode === 'major' ? tonic : spellPitch(tonic, 3, 2);
  const from = (
    semitones: number,
    letters: number,
    quality: ChordQuality = 'major',
  ): Chord => ({ root: spellPitch(major, semitones, letters), quality });
  const C = from(0, 0),
    F = from(5, 3),
    G = from(7, 4),
    Am = from(9, 5, 'minor');
  const Dm = from(2, 1, 'minor'),
    Em = from(4, 2, 'minor'),
    Fm = from(5, 3, 'minor');
  const D7 = from(2, 1, 'dominant7'),
    G7 = from(7, 4, 'dominant7'),
    E7 = from(4, 2, 'dominant7');
  const example = (
    title: string,
    chords: Chord[],
    context = C,
  ): LessonExample => ({ title, chords, context });
  switch (id) {
    case 'orientation':
      return [
        example('Диатонический оборот', [C, F, G, C]),
        example('Краска соседней тональности', [C, from(10, 6), F, C]),
      ];
    case 'parallel':
      return [
        example('Мажорная субдоминанта', [C, F, C]),
        example('Минорная субдоминанта', [C, F, Fm, C]),
      ];
    case 'context':
      return [
        example('Заимствование в мажоре', [C, Fm, C]),
        example('Тот же аккорд в параллельном миноре', [Am, Fm, Am], Am),
      ];
    case 'modulation':
      return [
        example('Краска и возврат', [Am, from(6, 3, 'minor'), Am], Am),
        example(
          'Продолжение к новому центру',
          [Am, from(6, 3, 'minor'), G, from(9, 5), from(2, 1)],
          Am,
        ),
      ];
    case 'melody':
      return [
        example('Ожидаемый приход', [C, E7, Am]),
        example('Отложенное разрешение', [C, E7, F, Fm, C]),
      ];
    case 'common':
      return [
        example('Связь трезвучий', [C, from(1, 0, 'minor'), C]),
        example('Две общие ноты', [
          from(0, 0, 'major7'),
          from(1, 0, 'minor7'),
          from(0, 0, 'major7'),
        ]),
        example('Тритоновая замена перед тоникой', [
          Dm,
          from(1, 1, 'dominant7'),
          C,
        ]),
      ];
    case 'secondary':
      return [
        example('Исходный оборот', [C, Dm, G7, C]),
        example('Двойная доминанта', [C, D7, G7, C]),
        example('Побочная ко второй ступени', [
          C,
          from(9, 5, 'dominant7'),
          Dm,
          G7,
          C,
        ]),
      ];
    case 'steps':
      return [
        example('Кварты и параллельные аккорды', [C, F, Dm, Am, C]),
        example('Повторяющийся медиантовый шаг', [
          C,
          Em,
          G,
          from(11, 6, 'minor'),
          from(2, 1),
          C,
        ]),
      ];
  }
};
