import { Melody } from 'app/services/MelodiesService/types';

import { Clef } from './Clef';
import { StaffNote } from './StaffNote';
import { layoutChord } from './chordLayout';
import { STAFF_CLEFS } from './clefs';
import { StaffSystem, layoutStaff } from './layout';
import { getStaffStep } from './notation';
import { playbackX, timeAtX } from './playback';

type PlaybackProps = {
  position?: number;
  soundingNoteIndices?: number[];
  onSeek?: (time: number) => void;
};

type StaffLineProps = PlaybackProps &
  (
    | { line: StaffSystem; bpm: number }
    | {
        melody: Melody;
        bpm: number;
        now: number;
      }
  );

// Keep the melody interface for other score previews in the application.
export const StaffLine = (props: StaffLineProps) => {
  const lines =
    'line' in props
      ? [props.line]
      : layoutStaff(props.melody, props.bpm, props.now, 900);
  return (
    <>
      {lines.map((line, index) => (
        <StaffSystemView
          key={index}
          line={line}
          bpm={props.bpm}
          position={props.position}
          soundingNoteIndices={props.soundingNoteIndices}
          onSeek={props.onSeek}
        />
      ))}
    </>
  );
};

const StaffSystemView = ({
  line,
  bpm,
  position,
  soundingNoteIndices = [],
  onSeek,
}: { line: StaffSystem; bpm: number } & PlaybackProps) => {
  const { top, bottom: bottomNote } = STAFF_CLEFS[line.clef];
  const topStep = getStaffStep(top);
  const bottomStep = getStaffStep(bottomNote);
  const signatureX = line.timeSignature.startsWith('12/') ? 66 : 60;
  const events = line.groups.flatMap(group => group.notes);
  const steps = events.map(({ note }) => getStaffStep(note));
  const maxStep = Math.max(topStep, ...steps);
  const minStep = Math.min(bottomStep, ...steps);
  const chords = line.groups.map(group => ({
    ...group,
    ...layoutChord(group, bpm, line.clef),
  }));
  const stems = chords.flatMap(chord =>
    chord.notes.flatMap(note => (note.stem ? [note.stem] : [])),
  );
  const topPadding = Math.max(
    28,
    ...stems.map(stem => (stem.endStep - maxStep) * 5 + 18),
  );
  const y = (step: number) => topPadding + (maxStep - step) * 5;
  const bottom = y(bottomStep);
  const height = Math.max(
    y(minStep) + 34,
    ...stems.map(stem => y(stem.endStep) + 18),
  );
  const cursorX =
    position === undefined ? undefined : playbackX(line, position);
  return (
    <svg
      width="100%"
      viewBox={`0 0 ${line.width} ${height}`}
      role="group"
      aria-label="Recorded notes"
      data-clef={line.clef}
      style={{ display: 'block', cursor: onSeek ? 'pointer' : undefined }}
      onClick={event => {
        if (!onSeek) return;
        const noteTime = (event.target as Element)
          .closest('[data-seek-time]')
          ?.getAttribute('data-seek-time');
        if (noteTime !== null && noteTime !== undefined) {
          onSeek(Number(noteTime));
          return;
        }
        const bounds = event.currentTarget.getBoundingClientRect();
        if (bounds.width)
          onSeek(
            timeAtX(
              line.timeline,
              ((event.clientX - bounds.left) / bounds.width) * line.width,
            ),
          );
      }}
    >
      {[0, 2, 4, 6, 8].map(step => (
        <line
          key={step}
          x1="0"
          x2={line.width}
          y1={bottom - step * 5}
          y2={bottom - step * 5}
          stroke="currentColor"
          opacity="0.4"
        />
      ))}
      <Clef
        clef={line.clef}
        y={y(getStaffStep(line.clef === 'bass' ? 'F3' : 'G4'))}
      />
      <g aria-label={`Размер ${line.timeSignature}`}>
        <text
          x={signatureX}
          y={bottom - 22}
          fontSize="19"
          fontWeight="bold"
          textAnchor="middle"
        >
          {line.timeSignature.split('/')[0]}
        </text>
        <text
          x={signatureX}
          y={bottom - 4}
          fontSize="19"
          fontWeight="bold"
          textAnchor="middle"
        >
          {line.timeSignature.split('/')[1]}
        </text>
      </g>
      {line.continuesMeasure && (
        <text x={signatureX === 66 ? 84 : 70} y="14" fontSize="11">
          Такт {line.measureNumber} (продолжение)
        </text>
      )}
      {line.barLines.map(bar => (
        <g
          key={bar.number}
          role="img"
          aria-label={`Такт ${bar.number}`}
          data-measure={bar.number}
        >
          <line
            x1={bar.x}
            x2={bar.x}
            y1={bottom - 40}
            y2={bottom}
            stroke="currentColor"
          />
          <text x={bar.x + 4} y="14" fontSize="11">
            {bar.number}
          </text>
        </g>
      ))}
      {line.closingBar && (
        <g data-closing-bar={line.closingBar.final ? 'final' : 'measure'}>
          <line
            x1={line.closingBar.x}
            x2={line.closingBar.x}
            y1={bottom - 40}
            y2={bottom}
            stroke="currentColor"
          />
          {line.closingBar.final && (
            <line
              x1={line.closingBar.x + 4}
              x2={line.closingBar.x + 4}
              y1={bottom - 40}
              y2={bottom}
              stroke="currentColor"
              strokeWidth="3"
            />
          )}
        </g>
      )}
      {line.beats.map(tick => (
        <g key={tick.x} opacity="0.25">
          {tick.number !== 1 && (
            <line
              x1={tick.x}
              x2={tick.x}
              y1={bottom - 48}
              y2={bottom + 16}
              stroke="currentColor"
              strokeDasharray="2 4"
            />
          )}
          <text x={tick.x} y={height - 8} fontSize="10" textAnchor="middle">
            {tick.number}
          </text>
        </g>
      ))}
      {onSeek && (
        <g aria-hidden="true">
          {chords.flatMap(group =>
            group.notes.map(({ event }) => (
              <rect
                key={event.index}
                data-seek-time={event.start}
                x={group.x + event.headOffset - 12}
                y={y(getStaffStep(event.note)) - 14}
                width="24"
                height="28"
                fill="transparent"
              />
            )),
          )}
        </g>
      )}
      {chords.map(group => (
        <g key={group.notes[0].event.index} data-staff-chord={group.start}>
          {group.notes.map(({ event, stem, dotOffset }) => {
            const step = getStaffStep(event.note);
            const ledgerSteps: number[] = [];
            for (let s = bottomStep - 2; s >= step; s -= 2) ledgerSteps.push(s);
            for (let s = topStep + 2; s <= step; s += 2) ledgerSteps.push(s);
            return (
              <g
                key={event.index}
                role={onSeek ? 'button' : undefined}
                tabIndex={onSeek ? 0 : undefined}
                aria-label={
                  onSeek
                    ? `Перейти к ноте ${event.index + 1}: ${event.note}`
                    : undefined
                }
                data-sounding={soundingNoteIndices.includes(event.index)}
                color={
                  soundingNoteIndices.includes(event.index)
                    ? 'var(--staff-playback, currentColor)'
                    : undefined
                }
                onClick={
                  onSeek
                    ? click => {
                        click.stopPropagation();
                        onSeek(event.start);
                      }
                    : undefined
                }
                onKeyDown={
                  onSeek
                    ? key => {
                        if (key.key === 'Enter' || key.key === ' ') {
                          key.preventDefault();
                          key.stopPropagation();
                          onSeek(event.start);
                        }
                      }
                    : undefined
                }
              >
                {ledgerSteps.map(s => (
                  <line
                    key={s}
                    x1={group.x + event.headOffset - 10}
                    x2={group.x + event.headOffset + 10}
                    y1={y(s)}
                    y2={y(s)}
                    stroke="currentColor"
                    opacity="0.6"
                  />
                ))}
                <StaffNote
                  event={event}
                  x={group.x}
                  y={y(step)}
                  bpm={bpm}
                  stem={stem}
                  dotOffset={dotOffset}
                  stepY={y}
                />
              </g>
            );
          })}
        </g>
      ))}
      {cursorX !== undefined && (
        <line
          data-testid="staff-playhead"
          data-position={Math.round(position!)}
          x1={cursorX}
          x2={cursorX}
          y1="18"
          y2={height - 20}
          stroke="var(--staff-playback, currentColor)"
          strokeWidth="2"
          pointerEvents="none"
          aria-hidden="true"
        />
      )}
    </svg>
  );
};
