import { useId, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';

import {
  applyEffectPreset,
  builtInEffectPresets,
  effectPresetCategories,
  matchesEffectPreset,
  normalizePresetName,
} from 'app/services/EffectsService/presets';
import { selectEffects } from 'app/services/EffectsService/selectors';
import { InstrumentEffects } from 'app/services/EffectsService/settings';
import { effectsActions } from 'app/services/EffectsService/slice';

import { PresetPedalboard } from './PresetPedalboard';

export const EffectPresets = ({
  settings,
  onChange,
}: {
  settings: InstrumentEffects;
  onChange: (settings: InstrumentEffects) => void;
}) => {
  const dispatch = useDispatch();
  const { customPresets = [], presetsPersistent } = useSelector(selectEffects);
  const [selectedId, setSelectedId] = useState(
    () =>
      [...customPresets, ...builtInEffectPresets].find(item =>
        matchesEffectPreset(item, settings),
      )?.id ?? '',
  );
  const [saving, setSaving] = useState(false);
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const id = useId();
  const presets = [...builtInEffectPresets, ...customPresets];
  const preferred = presets.find(item => item.id === selectedId);
  const selected =
    preferred ?? presets.find(item => matchesEffectPreset(item, settings));
  const modified = selected && !matchesEffectPreset(selected, settings);
  const custom = customPresets.some(item => item.id === selected?.id);

  return (
    <Panel aria-label="Пресеты эффектов">
      <Row>
        <Choice>
          Применить пресет целиком
          <select
            aria-label="Пресет эффектов"
            aria-describedby={`${id}-description`}
            value={modified ? '' : selected?.id ?? ''}
            onChange={event => {
              const next = presets.find(item => item.id === event.target.value);
              if (!next) return;
              setSelectedId(next.id);
              setMessage('');
              onChange(applyEffectPreset(next, settings));
              event.currentTarget.blur();
            }}
          >
            <option value="" disabled>
              {modified ? `${selected?.name} (изменён)` : 'Свои настройки'}
            </option>
            {effectPresetCategories.map(category => (
              <optgroup key={category.id} label={category.name}>
                {builtInEffectPresets
                  .filter(item => item.category === category.id)
                  .map(item => (
                    <option key={item.id} value={item.id}>
                      {item.name}
                    </option>
                  ))}
              </optgroup>
            ))}
            {customPresets.length > 0 && (
              <optgroup label="Мои пресеты">
                {customPresets.map(item => (
                  <option key={item.id} value={item.id}>
                    {item.name}
                  </option>
                ))}
              </optgroup>
            )}
          </select>
        </Choice>
        <button
          type="button"
          onClick={() => {
            setSaving(true);
            setName('');
            setError('');
            setMessage('');
          }}
        >
          Сохранить как…
        </button>
        {custom && selected && (
          <>
            <button
              type="button"
              disabled={!modified}
              onClick={() => {
                dispatch(effectsActions.savePreset({ ...selected, settings }));
                setMessage('Пресет обновлён.');
              }}
            >
              Обновить пресет
            </button>
            <button
              type="button"
              onClick={() => {
                dispatch(effectsActions.deletePreset(selected.id));
                setSelectedId('');
                setMessage('Пресет удалён. Текущие настройки сохранены.');
              }}
            >
              Удалить пресет
            </button>
          </>
        )}
      </Row>
      <Hint id={`${id}-description`}>
        {modified
          ? 'Настройки изменены. Сохраните их в свой пресет.'
          : selected?.description ??
            'Свои пресеты доступны для всех тембров и аудиовхода в этом браузере.'}{' '}
        Громкость сохраняется при выборе пресета.
      </Hint>
      <PresetPedalboard
        settings={settings}
        onChange={onChange}
        customPresets={customPresets}
      />
      {saving && (
        <SaveForm
          onSubmit={event => {
            event.preventDefault();
            const title = normalizePresetName(name);
            if (!title) {
              setError('Введите название пресета.');
              return;
            }
            if (
              customPresets.some(
                item =>
                  item.name.toLocaleLowerCase() === title.toLocaleLowerCase(),
              )
            ) {
              setError(
                'Такое название уже есть. Выберите другое или обновите существующий пресет.',
              );
              return;
            }
            const nextId = `custom-${Date.now().toString(36)}-${Math.random()
              .toString(36)
              .slice(2, 9)}`;
            dispatch(
              effectsActions.savePreset({ id: nextId, name: title, settings }),
            );
            setSelectedId(nextId);
            setSaving(false);
            setMessage('Пресет сохранён.');
          }}
        >
          <label>
            Название пресета
            <input
              autoFocus
              maxLength={60}
              value={name}
              aria-invalid={!!error}
              aria-describedby={error ? `${id}-error` : undefined}
              placeholder="Например, Моя гитара"
              onChange={event => {
                setName(event.target.value);
                setError('');
              }}
            />
          </label>
          <button type="submit">Сохранить пресет</button>
          <button type="button" onClick={() => setSaving(false)}>
            Отмена
          </button>
          {error && (
            <Hint id={`${id}-error`} role="alert">
              {error}
            </Hint>
          )}
        </SaveForm>
      )}
      {presetsPersistent === false ? (
        <Hint role="alert">
          Не удалось сохранить пресеты в браузере. Изменения доступны только до
          перезагрузки.
        </Hint>
      ) : (
        message && <Hint role="status">{message}</Hint>
      )}
    </Panel>
  );
};

const Panel = styled.section`
  margin-bottom: 16px;
  padding: 12px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  background: ${p => p.theme.background};
  font-size: 12px;
  button,
  select,
  input {
    min-height: 36px;
    box-sizing: border-box;
    padding: 6px 10px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    color: ${p => p.theme.text};
    background: ${p => p.theme.surface};
    font: inherit;
  }
  button {
    cursor: pointer;
  }
  button:disabled {
    opacity: 0.5;
    cursor: default;
  }
  input,
  select {
    width: 100%;
    min-width: 0;
  }
  label {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  :focus-visible {
    outline: 2px solid ${p => p.theme.primary};
    outline-offset: 2px;
  }
`;

const Row = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 8px;
`;

const Choice = styled.label`
  flex: 1 1 240px;
  min-width: 0;
`;

const Hint = styled.p`
  flex-basis: 100%;
  margin: 8px 0 0;
  color: ${p => p.theme.textSecondary};
  line-height: 1.5;
  &[role='alert'] {
    color: ${p => p.theme.danger};
  }
`;

const SaveForm = styled.form`
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 8px;
  margin-top: 12px;
  label {
    flex: 1 1 240px;
    min-width: 0;
  }
`;
