import type { GuitarSamples } from './capture';
import { RealtimeFrame, createPolyphonicStream } from './polyphonicStream';
import { RealtimeNote, createRealtimeTranscription } from './realtime';

export type RecordingMode = 'live' | 'live-mono' | 'polyphonic';
export type LiveTranscription = {
  readonly noteCount: number;
  push(chunk: GuitarSamples): void;
  finish(): void | Promise<void>;
  dispose(): void;
};

export const createLiveTranscription = (
  onFrame: (frame: RealtimeFrame) => void,
  onError: (error: Error) => void,
  mono = false,
  openWorker: () => Promise<Worker> = () =>
    import('./pitchWorker').then(api => api.openPitchWorker()),
): LiveTranscription => {
  if (mono) {
    let events: RealtimeNote[] = [];
    const stream = createRealtimeTranscription(event => events.push(event));
    const publish = () => {
      onFrame({
        events,
        soundingNotes: stream.soundingNotes,
        noteCount: stream.noteCount,
      });
      events = [];
    };
    return {
      get noteCount() {
        return stream.noteCount;
      },
      push(chunk) {
        stream.push(chunk);
        publish();
      },
      finish() {
        stream.finish();
        publish();
      },
      dispose: stream.dispose,
    };
  }
  // A synchronous implementation also supports hosts without Worker (and
  // deterministic DSP tests); normal browser capture uses the worker below.
  if (typeof Worker === 'undefined') return createPolyphonicStream(onFrame);
  let worker: Worker | undefined;
  let ready = false,
    busy = false,
    closing = false,
    disposed = false,
    count = 0;
  let queuedFrames = 0;
  const queue: GuitarSamples[] = [];
  let failed: Error | undefined;
  let resolveFinish: (() => void) | undefined;
  let rejectFinish: ((error: Error) => void) | undefined;
  let finished: Promise<void> | undefined;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let finishTimer: ReturnType<typeof setTimeout> | undefined;
  const release = () => {
    if (timer) clearTimeout(timer);
    if (finishTimer) clearTimeout(finishTimer);
    queue.length = 0;
    queuedFrames = 0;
    worker?.terminate();
    worker = undefined;
  };
  const fail = (error: Error) => {
    if (disposed || failed) return;
    failed = error;
    release();
    rejectFinish?.(error);
    onError(error);
  };
  const pump = () => {
    if (!worker || !ready || busy || disposed || failed) return;
    const chunk = queue.shift();
    if (chunk) {
      queuedFrames -= chunk.samples.length;
      busy = true;
      worker.postMessage({ type: 'samples', chunk }, [chunk.samples.buffer]);
    } else if (closing) {
      busy = true;
      worker.postMessage({ type: 'finish' });
    }
  };
  timer = setTimeout(
    () =>
      fail(
        new Error(
          'Не удалось запустить живое распознавание. Выберите быстрый одноголосный режим.',
        ),
      ),
    10000,
  );
  void openWorker()
    .then(value => {
      if (disposed || failed) {
        value.terminate();
        return;
      }
      worker = value;
      worker.onerror = () =>
        fail(
          new Error(
            'Живое распознавание прервано. Исходное аудио сохраняется; попробуйте быстрый одноголосный режим.',
          ),
        );
      worker.onmessage = ({ data }) => {
        if (disposed || failed) return;
        if (data.type === 'ready') {
          ready = true;
          if (timer) clearTimeout(timer);
          pump();
        } else if (data.type === 'frame') {
          count = data.frame.noteCount;
          onFrame(data.frame);
        } else if (data.type === 'ack') {
          busy = false;
          pump();
        } else if (data.type === 'done') {
          resolveFinish?.();
          disposed = true;
          release();
        } else if (data.type === 'error')
          fail(
            new Error(
              'Не удалось распознать аудиопоток. Исходное аудио сохраняется.',
            ),
          );
      };
    })
    .catch(() =>
      fail(
        new Error(
          'Не удалось загрузить живое распознавание. Выберите быстрый одноголосный режим.',
        ),
      ),
    );
  return {
    get noteCount() {
      return count;
    },
    push(chunk) {
      if (disposed || failed || closing) return;
      // Never transfer the original PCM, which is still needed for raw WAV.
      queue.push({ ...chunk, samples: chunk.samples.slice() });
      queuedFrames += chunk.samples.length;
      if (queuedFrames > chunk.sampleRate * 2) {
        fail(
          new Error(
            'Устройство не успевает распознавать поток. Аудио продолжает записываться; выберите быстрый одноголосный режим для следующего дубля.',
          ),
        );
        return;
      }
      pump();
    },
    finish() {
      if (finished) return finished;
      if (failed) return Promise.reject(failed);
      if (disposed) return Promise.resolve();
      closing = true;
      finished = new Promise<void>((resolve, reject) => {
        resolveFinish = resolve;
        rejectFinish = reject;
      });
      if (timer) clearTimeout(timer);
      finishTimer = setTimeout(
        () =>
          fail(
            new Error(
              'Не удалось завершить живое распознавание. Исходное аудио доступно как WAV.',
            ),
          ),
        5000,
      );
      pump();
      return finished;
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      release();
      rejectFinish?.(new DOMException('Recognition cancelled', 'AbortError'));
    },
  };
};
