import { StaffSystem } from './layout';

export type TimeAnchor = { time: number; x: number };

// Space reserved for symbols is not proportional to time. Both directions use
// the same anchors; equal times between a bar and its first attack are valid.
export const timeAtX = (anchors: TimeAnchor[], x: number) => {
  const next = anchors.findIndex(anchor => anchor.x > x);
  if (next === 0) return anchors[0].time;
  if (next === -1) return anchors[anchors.length - 1].time;
  const a = anchors[next - 1];
  const b = anchors[next];
  return a.time + ((x - a.x) / (b.x - a.x)) * (b.time - a.time);
};

export const playbackX = (line: StaffSystem, time: number) => {
  const { timeline } = line;
  const first = timeline[0];
  const last = timeline[timeline.length - 1];
  // A boundary belongs to the following system, except the score's final end.
  if (
    time < first.time ||
    time > last.time ||
    (time === last.time && !line.closingBar?.final)
  )
    return undefined;
  const next = timeline.findIndex(anchor => anchor.time > time);
  if (next === -1) return last.x;
  const a = timeline[Math.max(0, next - 1)];
  const b = timeline[next];
  return a.x + ((time - a.time) / (b.time - a.time)) * (b.x - a.x);
};
