import { useEffect, useRef } from 'react';
import { batch, useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';

import { Note, notesActions } from 'app/services/NotesService';
import { selectSettings } from 'app/services/SettingsService';
import { Timbre } from 'app/services/SynthesizerService';

import { toClassName } from 'utils/className';

export const PianoKey = ({
  note,
  isPressed,
  isHighlighted,
}: {
  note: Note;
  isPressed: boolean;
  isHighlighted: boolean;
}) => {
  const dispatch = useDispatch();
  const isSharp = note.includes('#');
  const { timbre, isRecording } = useSelector(selectSettings);
  const played = useRef<{
    pointerId: number;
    timbre: Timbre;
    recorded: boolean;
  }>();

  const release = () => {
    const active = played.current;
    if (!active) return;
    played.current = undefined;
    batch(() => {
      dispatch(notesActions.muteNote({ timbre: active.timbre, note }));
      if (active.recorded) dispatch(notesActions.logEndingNote(note));
    });
  };

  const start = (pointerId: number) => {
    if (played.current) return;
    played.current = { pointerId, timbre, recorded: isRecording };
    batch(() => {
      dispatch(notesActions.playNote({ timbre, note }));
      if (isRecording) dispatch(notesActions.logStartingNote(note));
    });
  };

  useEffect(() => {
    const releasePointer = (event: PointerEvent) => {
      if (played.current?.pointerId === event.pointerId) release();
    };
    const hide = () => {
      if (document.hidden) release();
    };
    window.addEventListener('pointerup', releasePointer);
    window.addEventListener('pointercancel', releasePointer);
    window.addEventListener('blur', release);
    document.addEventListener('visibilitychange', hide);
    return () => {
      release();
      window.removeEventListener('pointerup', releasePointer);
      window.removeEventListener('pointercancel', releasePointer);
      window.removeEventListener('blur', release);
      document.removeEventListener('visibilitychange', hide);
    };
    // The active gesture remembers its original timbre and recording state.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dispatch, note]);

  return (
    <PianoKeyWrapper
      className={toClassName({
        black: isSharp,
        white: !isSharp,
        pressed: isPressed,
        highlighted: isHighlighted,
      })}
      role="button"
      aria-label={`Play ${note}`}
      data-note={note}
      onPointerDown={event => {
        if (event.button !== 0) return;
        event.preventDefault();
        // Let a sliding finger enter adjacent keys instead of capturing it.
        if (event.currentTarget.hasPointerCapture?.(event.pointerId)) {
          event.currentTarget.releasePointerCapture(event.pointerId);
        }
        start(event.pointerId);
      }}
      onPointerEnter={event => {
        if (event.buttons & 1) start(event.pointerId);
      }}
      onPointerUp={event => {
        if (played.current?.pointerId === event.pointerId) release();
      }}
      onPointerLeave={event => {
        if (played.current?.pointerId === event.pointerId) release();
      }}
      onPointerCancel={event => {
        if (played.current?.pointerId === event.pointerId) release();
      }}
    >
      {isSharp ? <SharpNoteTitle note={note} /> : note}
    </PianoKeyWrapper>
  );
};

const SharpNoteTitle = ({ note }) =>
  note
    .split('')
    .map(char => <NoteChar key={`key-${note}-char-${char}`} char={char} />);

const NoteChar = ({ char }) => (char === '#' ? <sup>#</sup> : char);

const PianoKeyWrapper = styled.div`
  font-size: 0.5rem;
  text-align: center;
  position: relative;
  border-bottom-left-radius: 3px;
  border-bottom-right-radius: 3px;
  cursor: pointer;
  vertical-align: bottom;
  user-select: none;
  touch-action: none;
  transition: background-color 200ms;

  &.white {
    color: ${p => p.theme.piano.onWhite};
    height: 100px;
    width: 20px;
    border: 1px solid ${p => p.theme.piano.border};
    line-height: 180px;
    background-color: ${p => p.theme.piano.white};

    &:hover {
      background-color: ${p => p.theme.piano.whiteHover};
    }
  }

  &.black {
    height: 70px;
    width: 16px;
    background-color: ${p => p.theme.piano.black};
    margin-right: -16px;
    left: -8px;
    color: ${p => p.theme.piano.onBlack};
    z-index: 1;
    line-height: 120px;

    &:hover {
      background-color: ${p => p.theme.piano.blackHover};
    }
  }

  &.highlighted {
    background-color: ${p => p.theme.piano.available};

    &.black {
      background-color: ${p => p.theme.piano.availableSharp};
    }
  }

  &.pressed,
  &.pressed.black {
    background-color: ${p => p.theme.keycap.active};
    color: ${p => p.theme.keycap.onActive};

    &:hover {
      background-color: ${p => p.theme.keycap.active};
      color: ${p => p.theme.keycap.onActive};
    }
  }
`;
